def name_operands(region,address,operation):
 if region in ('Station','Text'):operation=operation.replace('(#983A)','(@ScriptCallState.EventCode)')
 if region!='Station':return operation
 for value,name in ((0x7068,'ScriptSelection.CargoRow'),(0x7026,'ScriptSelection.CargoBase'),(0x7062,'TradePanelState.HoverArea'),(0x7063,'TradePanelState.HoverRows'),(0x983A,'ScriptCallState.EventCode')):
  operation=operation.replace('(#'+format(value,'04X')+')','(@'+name+')')
 if address not in FUNCTIONS:return operation
 for old,new in (('CALL #C85E','CALL @Station.CloseMenuOnRow.Entry'),('JP #C873','JP @Station.DropItemDraw.Entry'),('(#7D78)','(@DrawItemState.Index35)'),('(#6307)','(@StationState.PointerXY)'),('(#AEBB)','(@TextWindow.OriginXLow)'),('CALL #C000','CALL @Text.RunMarketScript.Entry'),('LD HL, #7071','LD HL, @Station.DrawTradePanel.Entry'),('LD HL, #708E','LD HL, @Station.DrawTradePanel.DrawColumns'),('LD HL, #EBF3','LD HL, @TradeTableText.Header'),('LD HL, #001D','LD HL, @TradePanelConst.EndLimit'),('LD A, #20','LD A, @TradeTableConst.StartY'),('LD A, #FF','LD A, @TradePanelConst.NoRow'),('CP #87','CP @TradePanelConst.OwnedColumnX'),('LD A, #0A','LD A, @TradeEvent.SellOne'),('LD A, #16','LD A, @TradePanelConst.LanguagePage'),('LD A, #10','LD A, @ScreenUpdateConst.VisiblePage'),('LD DE, #1E23','LD DE, @TradePanelConst.HoverAreaInit')):
  operation=operation.replace(old,new)
 return operation
